"""Kernel generado por kaggle/construir_kernels.py — no editar a mano."""
import glob, os, shutil, subprocess, sys
W = "/kaggle/working"
open(os.path.join(W, "map_modelos.py"), "w").write('"""Componentes compartidos del proyecto MAP.\n\nPreprocesamiento, particiones, representación TF-IDF, modelos lineales y\nmétricas. Lo usan los scripts de entrenamiento (notebooks/) y la aplicación\nStreamlit (app/), de modo que una explicación nueva se transforma exactamente\nigual que los datos de entrenamiento y los modelos guardados con joblib pueden\ncargarse desde cualquiera de ellos.\n"""\n\nimport re\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom scipy import sparse\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.model_selection import StratifiedGroupKFold\nfrom sklearn.preprocessing import OneHotEncoder\nfrom sklearn.svm import LinearSVC\n\nROOT = Path(__file__).resolve().parent\nRANDOM_STATE = 42\n\n\ndef ruta_datos() -> Path:\n    for p in (ROOT / "data", ROOT / "data" / "raw"):\n        if (p / "train.csv").exists():\n            return p\n    raise FileNotFoundError("No se encontró data/train.csv (descárguelo con la API de Kaggle).")\n\n\n# ---------------------------------------------------------------------------\n# Preprocesamiento (mismas decisiones que el análisis exploratorio)\n# ---------------------------------------------------------------------------\ndef limpiar_latex(t: str) -> str:\n    """Convierte la notación LaTeX de las opciones a texto plano: \\\\frac{1}{3} -> 1/3."""\n    t = str(t)\n    t = re.sub(r"\\\\frac\\{([^}]*)\\}\\{([^}]*)\\}", r"\\1/\\2", t)\n    t = re.sub(r"\\\\[a-zA-Z]+", " ", t)\n    t = t.replace("\\\\(", " ").replace("\\\\)", " ")\n    t = re.sub(r"[{}$]", " ", t)\n    return re.sub(r"\\s+", " ", t).strip()\n\n\ndef preprocesar(df: pd.DataFrame) -> pd.DataFrame:\n    """Normaliza una tabla con QuestionId, QuestionText, MC_Answer y StudentExplanation."""\n    df = df.copy()\n    df["MC_Answer_clean"] = df["MC_Answer"].apply(limpiar_latex)\n    df["Explanation_clean"] = (\n        df["StudentExplanation"].fillna("").astype(str).str.lower()\n        .str.replace(r"\\s+", " ", regex=True).str.strip()\n    )\n    df["QA"] = df["QuestionId"].astype(str) + "|" + df["MC_Answer_clean"]\n    if "QuestionText" in df:\n        df["Question_clean"] = df["QuestionText"].apply(limpiar_latex)\n    return df\n\n\ndef cargar_train() -> pd.DataFrame:\n    train = pd.read_csv(ruta_datos() / "train.csv")\n    train["Misconception"] = train["Misconception"].fillna("NA")\n    train["target"] = train["Category"] + ":" + train["Misconception"]\n    train["Veracidad"] = train["Category"].str.split("_").str[0]\n    train["Tipo"] = train["Category"].str.split("_").str[1]\n    return preprocesar(train)\n\n\ndef texto_transformer(df: pd.DataFrame) -> list:\n    """Entrada contextual: pregunta + opción + explicación."""\n    return ("Question: " + df["Question_clean"] + " Answer: " + df["MC_Answer_clean"]\n            + " Explanation: " + df["StudentExplanation"].fillna("").astype(str)).tolist()\n\n\n# ---------------------------------------------------------------------------\n# Particiones\n# ---------------------------------------------------------------------------\ndef grupos_duplicados(df: pd.DataFrame) -> np.ndarray:\n    """Agrupa explicaciones idénticas de una misma pregunta (evita fuga por duplicados)."""\n    return (df["QuestionId"].astype(str) + "|" + df["Explanation_clean"]).factorize()[0]\n\n\ndef particiones(df: pd.DataFrame):\n    """Devuelve índices (entrenamiento, validación, prueba).\n\n    Prueba = 20 % (StratifiedGroupKFold de 5 pliegues, pliegue 0).\n    Validación = 10 % del entrenamiento (StratifiedGroupKFold de 10 pliegues),\n    usada para detener el Transformer, calibrar y pesar el ensamble.\n    """\n    g = grupos_duplicados(df)\n    sgkf = StratifiedGroupKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)\n    idx_tr, idx_te = next(sgkf.split(df, df["target"], groups=g))\n    sub = df.iloc[idx_tr]\n    sgkf2 = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)\n    a, b = next(sgkf2.split(sub, sub["target"], groups=g[idx_tr]))\n    return idx_tr, idx_tr[a], idx_tr[b], idx_te  # train completo, train sin val, val, test\n\n\n# ---------------------------------------------------------------------------\n# Representación TF-IDF\n# ---------------------------------------------------------------------------\nclass Featurizer:\n    """TF-IDF de palabras (1-2) y caracteres (2-5) + contexto categórico opcional.\n\n    contexto: "ninguno" (texto solo), "pregunta" (one-hot de QuestionId) o\n    "pregunta+opcion" (one-hot de QuestionId y del par pregunta-opción).\n    """\n\n    def __init__(self, contexto="pregunta+opcion"):\n        self.contexto = contexto\n        self.word = TfidfVectorizer(ngram_range=(1, 2), min_df=2, sublinear_tf=True,\n                                    token_pattern=r"(?u)\\b\\w+\\b|[+\\-*/=<>%]")\n        self.char = TfidfVectorizer(analyzer="char_wb", ngram_range=(2, 5), min_df=3,\n                                    sublinear_tf=True, max_features=120_000)\n        self.ohe = OneHotEncoder(handle_unknown="ignore")\n\n    def _cols(self):\n        return {"ninguno": [], "pregunta": ["QuestionId"],\n                "pregunta+opcion": ["QuestionId", "QA"]}[self.contexto]\n\n    def fit(self, d):\n        self.word.fit(d["Explanation_clean"])\n        self.char.fit(d["Explanation_clean"])\n        if self._cols():\n            self.ohe.fit(d[self._cols()].astype(str))\n        return self\n\n    def transform(self, d):\n        bloques = [self.word.transform(d["Explanation_clean"]),\n                   self.char.transform(d["Explanation_clean"])]\n        if self._cols():\n            bloques.append(self.ohe.transform(d[self._cols()].astype(str)))\n        return sparse.hstack(bloques).tocsr()\n\n\n# ---------------------------------------------------------------------------\n# Modelos\n# ---------------------------------------------------------------------------\nclass BaselinePreguntaOpcion:\n    """Sin texto: ordena las etiquetas por frecuencia dentro de (pregunta, opción)."""\n\n    nombre_corto = "Prior"\n\n    def fit(self, d, y):\n        self.classes_ = np.array(sorted(pd.unique(y)))\n        tabla = pd.crosstab(d["QA"].values, np.asarray(y))\n        self.tabla = {qa: np.array([fila.get(c, 0) for c in self.classes_], float)\n                      for qa, fila in tabla.iterrows()}\n        glob = pd.Series(y).value_counts()\n        self.glob = np.array([glob.get(c, 0) for c in self.classes_], float)\n        return self\n\n    def scores(self, d):\n        s = np.vstack([self.tabla.get(qa, self.glob) for qa in d["QA"]])\n        return s / s.sum(axis=1, keepdims=True).clip(1e-12)\n\n\nclass ModeloTexto:\n    """Featurizer + clasificador lineal de scikit-learn."""\n\n    def __init__(self, estimador, contexto="pregunta+opcion"):\n        self.est = estimador\n        self.contexto = contexto\n\n    def fit(self, d, y):\n        self.feat = Featurizer(self.contexto).fit(d)\n        self.est.fit(self.feat.transform(d), y)\n        self.classes_ = self.est.classes_\n        return self\n\n    def scores(self, d):\n        X = self.feat.transform(d)\n        if hasattr(self.est, "predict_proba"):\n            return self.est.predict_proba(X)\n        return self.est.decision_function(X)\n\n\nclass LogisticaJerarquica(ModeloTexto):\n    """Regresión logística + restricción jerárquica.\n\n    1) La veracidad se toma de la tabla (pregunta, opción), casi determinista.\n    2) Solo se permiten etiquetas compatibles con esa veracidad y observadas\n       para la misma pregunta en entrenamiento.\n    """\n\n    def fit(self, d, y):\n        super().fit(d, y)\n        y = pd.Series(np.asarray(y))\n        self.veracidad = (d.assign(v=y.str.split("_").str[0].values)\n                          .groupby("QA")["v"].agg(lambda s: s.value_counts().index[0]).to_dict())\n        self.permitidas = {q: set(sub["y"]) for q, sub in\n                           pd.DataFrame({"q": d["QuestionId"].values, "y": y.values}).groupby("q")}\n        return self\n\n    def mascara(self, d):\n        ver = np.array([c.split("_")[0] for c in self.classes_])\n        m = np.ones((len(d), len(self.classes_)), bool)\n        for i, (q, qa) in enumerate(zip(d["QuestionId"], d["QA"])):\n            if q in self.permitidas:\n                m[i] &= np.isin(self.classes_, list(self.permitidas[q]))\n            if qa in self.veracidad:\n                m[i] &= ver == self.veracidad[qa]\n            if not m[i].any():\n                m[i] = True\n        return m\n\n    def scores(self, d):\n        p = super().scores(d) * self.mascara(d)\n        return p / p.sum(axis=1, keepdims=True).clip(1e-12)\n\n\ndef crear(nombre, contexto="pregunta+opcion", **hp):\n    if nombre == "Prior (pregunta+opción)":\n        return BaselinePreguntaOpcion()\n    if nombre == "TF-IDF + SVM lineal":\n        return ModeloTexto(LinearSVC(C=hp.get("C", 0.3), class_weight=hp.get("class_weight"),\n                                     max_iter=5000, random_state=RANDOM_STATE), contexto)\n    lr = LogisticRegression(C=hp.get("C", 4.0), class_weight=hp.get("class_weight"),\n                            max_iter=3000, random_state=RANDOM_STATE)\n    if nombre == "TF-IDF + Regresión logística":\n        return ModeloTexto(lr, contexto)\n    if nombre == "TF-IDF + Regresión logística jerárquica":\n        return LogisticaJerarquica(lr, contexto)\n    raise ValueError(nombre)\n\n\ndef alinear(scores, clases_modelo, clases_globales):\n    """Reordena una matriz de puntajes al orden de clases_globales (columnas faltantes = 0)."""\n    pos = {c: i for i, c in enumerate(clases_modelo)}\n    out = np.zeros((scores.shape[0], len(clases_globales)))\n    for j, c in enumerate(clases_globales):\n        if c in pos:\n            out[:, j] = scores[:, pos[c]]\n    return out\n\n\ndef softmax(z, T=1.0):\n    z = np.asarray(z, float) / T\n    z = z - z.max(axis=1, keepdims=True)\n    e = np.exp(z)\n    return e / e.sum(axis=1, keepdims=True)\n\n\n# ---------------------------------------------------------------------------\n# Métricas\n# ---------------------------------------------------------------------------\ndef top_k(scores, classes, k=3):\n    return np.asarray(classes)[np.argsort(-scores, axis=1)[:, :k]]\n\n\ndef map_at_3_filas(y_true, top3):\n    pesos = np.array([1.0, 1 / 2, 1 / 3])\n    return ((np.asarray(top3) == np.asarray(y_true)[:, None]) * pesos).sum(axis=1)\n\n\ndef map_at_3(y_true, top3):\n    return float(map_at_3_filas(y_true, top3).mean())\n\n\ndef metricas(y_true, top3):\n    from sklearn.metrics import accuracy_score, f1_score\n    y_pred = np.asarray(top3)[:, 0]\n    return {\n        "MAP@3": map_at_3(y_true, top3),\n        "Accuracy": accuracy_score(y_true, y_pred),\n        "Top-3 accuracy": float((np.asarray(top3) == np.asarray(y_true)[:, None]).any(axis=1).mean()),\n        "Macro-F1": f1_score(y_true, y_pred, average="macro", zero_division=0),\n        "Weighted-F1": f1_score(y_true, y_pred, average="weighted", zero_division=0),\n    }\n\n\ndef ece(probs, y_idx, bins=15):\n    """Error de calibración esperado (Expected Calibration Error) de la primera predicción."""\n    conf = probs.max(axis=1)\n    acierto = probs.argmax(axis=1) == y_idx\n    bordes = np.linspace(0, 1, bins + 1)\n    total = 0.0\n    for lo, hi in zip(bordes[:-1], bordes[1:]):\n        m = (conf > lo) & (conf <= hi)\n        if m.any():\n            total += m.mean() * abs(acierto[m].mean() - conf[m].mean())\n    return float(total)\n')
os.makedirs(os.path.join(W, "notebooks"), exist_ok=True)
open(os.path.join(W, "notebooks", "03_transformer.py"), "w").write('"""Ajuste fino de DeBERTa-v3 para el reto MAP.\n\nEntrada contextual: "Question: <pregunta> Answer: <opción> Explanation: <explicación>".\nSalida: una de las 65 etiquetas Category:Misconception.\n\nModos:\n    python notebooks/03_transformer.py            # validación A (partición estratificada)\n    python notebooks/03_transformer.py --grupos   # validación B (GroupKFold por QuestionId)\n\nUsa la GPU de Apple (MPS) o CUDA si están disponibles.\n"""\n\nimport argparse\nimport json\nimport math\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom sklearn.model_selection import GroupKFold\nfrom transformers import (AutoModelForSequenceClassification, AutoTokenizer,\n                          get_linear_schedule_with_warmup)\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nimport map_modelos as mm  # noqa: E402\n\nap = argparse.ArgumentParser()\nap.add_argument("--modelo", default="microsoft/deberta-v3-small")\nap.add_argument("--epocas", type=int, default=3)\nap.add_argument("--lr", type=float, default=5e-5)\nap.add_argument("--batch", type=int, default=16)\nap.add_argument("--max_len", type=int, default=160)\nap.add_argument("--grupos", action="store_true")\nap.add_argument("--epocas_grupos", type=int, default=1)\nap.add_argument("--muestra", type=int, default=0, help="solo para pruebas: limita las filas")\nap.add_argument("--prefijo", default="deberta", help="prefijo de los archivos de salida")\nargs = ap.parse_args()\n\nOUT = mm.ROOT / "results"\nDIR_MODELO = mm.ROOT / "models" / f"{args.prefijo}_map"\nOUT.mkdir(exist_ok=True)\ntorch.manual_seed(mm.RANDOM_STATE)\nnp.random.seed(mm.RANDOM_STATE)\nDEV = torch.device("cuda" if torch.cuda.is_available()\n                   else "mps" if torch.backends.mps.is_available() else "cpu")\n\ndf = mm.cargar_train()\nCLASES = np.array(sorted(df["target"].unique()))\nIDX = {c: i for i, c in enumerate(CLASES)}\ny_all = df["target"].map(IDX).values\ntok = AutoTokenizer.from_pretrained(args.modelo)\ntextos = mm.texto_transformer(df)\nenc = tok(textos, truncation=True, max_length=args.max_len)\nlargos = np.array([len(x) for x in enc["input_ids"]])\nprint(f"Dispositivo: {DEV} · tokens p95 = {np.percentile(largos, 95):.0f}", flush=True)\n\n\ndef lotes(indices, barajar):\n    """Agrupa por longitud similar para minimizar el relleno."""\n    indices = np.asarray(indices)\n    if barajar:\n        indices = np.random.permutation(indices)\n        trozos = [indices[i:i + args.batch * 50] for i in range(0, len(indices), args.batch * 50)]\n        orden = np.concatenate([t[np.argsort(largos[t])] for t in trozos])\n        bs = [orden[i:i + args.batch] for i in range(0, len(orden), args.batch)]\n        return [bs[i] for i in np.random.permutation(len(bs))]\n    orden = indices[np.argsort(largos[indices])]\n    return [orden[i:i + args.batch * 4] for i in range(0, len(orden), args.batch * 4)]\n\n\ndef tensores(idx):\n    b = tok.pad({"input_ids": [enc["input_ids"][i] for i in idx],\n                 "attention_mask": [enc["attention_mask"][i] for i in idx]}, return_tensors="pt")\n    return {k: v.to(DEV) for k, v in b.items()}\n\n\n@torch.no_grad()\ndef logits_de(modelo, indices):\n    modelo.eval()\n    salida = np.zeros((len(indices), len(CLASES)), np.float32)\n    pos = {j: i for i, j in enumerate(indices)}\n    for idx in lotes(indices, barajar=False):\n        with torch.autocast(DEV.type, dtype=torch.float16, enabled=DEV.type == "cuda"):\n            z = modelo(**tensores(idx)).logits.float().cpu().numpy()\n        salida[[pos[j] for j in idx]] = z\n    return salida\n\n\ndef entrenar(idx_tr, idx_val=None, epocas=3):\n    modelo = AutoModelForSequenceClassification.from_pretrained(\n        args.modelo, num_labels=len(CLASES)).float().to(DEV)\n    if DEV.type == "mps":\n        # En equipos con memoria unificada limitada se congela la matriz de embeddings\n        # del vocabulario, lo que reduce la memoria de gradientes y del optimizador.\n        modelo.get_input_embeddings().weight.requires_grad_(False)\n    opt = torch.optim.AdamW([p for p in modelo.parameters() if p.requires_grad],\n                            lr=args.lr, weight_decay=0.01)\n    pasos = epocas * math.ceil(len(idx_tr) / args.batch)\n    sched = get_linear_schedule_with_warmup(opt, int(0.1 * pasos), pasos)\n    y_t = torch.tensor(y_all)\n    amp = DEV.type == "cuda"  # precisión mixta (fp16) en GPU NVIDIA\n    escala = torch.amp.GradScaler("cuda", enabled=amp)\n    historia, mejor, mejor_estado = [], -1, None\n    for ep in range(1, epocas + 1):\n        modelo.train()\n        t0, perdida = time.time(), 0.0\n        bs = lotes(idx_tr, barajar=True)\n        for k, idx in enumerate(bs, 1):\n            with torch.autocast(DEV.type, dtype=torch.float16, enabled=amp):\n                out = modelo(**tensores(idx), labels=y_t[idx].to(DEV))\n            escala.scale(out.loss).backward()\n            escala.unscale_(opt)\n            torch.nn.utils.clip_grad_norm_(modelo.parameters(), 1.0)\n            escala.step(opt); escala.update(); sched.step(); opt.zero_grad()\n            perdida += out.loss.item()\n            if k % 200 == 0:\n                print(f"  época {ep} · lote {k}/{len(bs)} · pérdida {perdida / k:.4f} · "\n                      f"{(time.time() - t0) / k * (len(bs) - k) / 60:.1f} min restantes", flush=True)\n        reg = {"época": ep, "pérdida": perdida / len(bs), "minutos": (time.time() - t0) / 60}\n        if idx_val is not None:\n            z = logits_de(modelo, idx_val)\n            reg["MAP@3 val"] = mm.map_at_3(CLASES[y_all[idx_val]], mm.top_k(z, CLASES))\n            if reg["MAP@3 val"] > mejor:\n                mejor = reg["MAP@3 val"]\n                mejor_estado = {k: v.detach().cpu().clone() for k, v in modelo.state_dict().items()}\n        historia.append(reg)\n        print("  ", reg, flush=True)\n    if mejor_estado is not None:\n        modelo.load_state_dict(mejor_estado)\n    return modelo, historia\n\n\nif not args.grupos:\n    # ----------------------- Validación A ---------------------------------\n    idx_full, idx_tr, idx_val, idx_te = mm.particiones(df)\n    if args.muestra:\n        idx_tr, idx_val, idx_te = idx_tr[:args.muestra], idx_val[:args.muestra], idx_te[:args.muestra]\n    t0 = time.time()\n    modelo, historia = entrenar(idx_tr, idx_val, args.epocas)\n    t_fit = time.time() - t0\n    t0 = time.time()\n    z_te = logits_de(modelo, idx_te)\n    t_pred = time.time() - t0\n    z_val = logits_de(modelo, idx_val)\n    np.save(OUT / f"{args.prefijo}_logits_val.npy", z_val)\n    np.save(OUT / f"{args.prefijo}_logits_test.npy", z_te)\n    DIR_MODELO.mkdir(parents=True, exist_ok=True)\n    modelo.half().save_pretrained(DIR_MODELO)\n    tok.save_pretrained(DIR_MODELO)\n    (DIR_MODELO / "clases.json").write_text(json.dumps(CLASES.tolist(), ensure_ascii=False))\n    m = mm.metricas(CLASES[y_all[idx_te]], mm.top_k(z_te, CLASES))\n    resumen = {"modelo_base": args.modelo, "hiperparametros": vars(args), "historia": historia,\n               "entrenamiento_s": t_fit, "prediccion_s": t_pred, "dispositivo": str(DEV),\n               "prueba": m}\n    (OUT / f"{args.prefijo}_resumen.json").write_text(json.dumps(resumen, indent=2, ensure_ascii=False))\n    print("[TEST]", m, flush=True)\nelse:\n    # ----------------------- Validación B ---------------------------------\n    res = []\n    for k, (a, b) in enumerate(GroupKFold(n_splits=3).split(df, groups=df["QuestionId"]), 1):\n        if args.muestra:\n            a, b = a[:args.muestra], b[:args.muestra]\n        print(f"Pliegue {k}: preguntas no vistas {sorted(df[\'QuestionId\'].iloc[b].unique())}", flush=True)\n        modelo, _ = entrenar(a, None, args.epocas_grupos)\n        z = logits_de(modelo, b)\n        top3 = mm.top_k(z, CLASES)\n        res.append({"pliegue": k, "MAP@3": mm.map_at_3(CLASES[y_all[b]], top3),\n                    "Accuracy Category": float(np.mean(\n                        [p.split(":")[0] == t.split(":")[0] for p, t in zip(top3[:, 0], CLASES[y_all[b]])]))})\n        print("  ", res[-1], flush=True)\n        del modelo\n        if DEV.type == "mps":\n            torch.mps.empty_cache()\n    (OUT / f"{args.prefijo}_grupos.json").write_text(json.dumps(\n        {"epocas": args.epocas_grupos, "pliegues": res,\n         "MAP@3 media": float(np.mean([r["MAP@3"] for r in res]))}, indent=2, ensure_ascii=False))\n')
